# Non-English dictionaries: [word, phonetic/pinyin, pos, definition EN, example native, example EN]
def conv(rows, lang):
    out=[]
    for i,r in enumerate(rows):
        w,ph,pos,definition,ex,exen = r
        out.append([w,w,ph,pos,definition,w,ex,i+1,[]])
    return out

